"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[1961],{7853(e){e.exports=JSON.parse('{"tag":{"label":"modes","permalink":"/pt-BR/tags/modes","allTagsPath":"/pt-BR/tags","count":17,"items":[{"id":"modes/personal-stale-files","title":"Arquivos pessoais sem uso","description":"O modo s\xf3 interativo que encontra arquivos grandes, sem uso h\xe1 muito tempo, em ~/Downloads e nas ra\xedzes sem prote\xe7\xe3o configuradas.","permalink":"/pt-BR/modes/personal-stale-files"},{"id":"modes/home-audit","title":"Auditoria da pasta pessoal","description":"Uma lista somente leitura das 20 maiores entradas da sua pasta pessoal, o linux-cleanup consiga limp\xe1-las ou n\xe3o \u2014 o jeito mais r\xe1pido de descobrir o que realmente est\xe1 ocupando o disco.","permalink":"/pt-BR/modes/home-audit"},{"id":"modes/globals-audit","title":"Auditoria de pacotes globais","description":"Uma auditoria somente leitura dos pacotes instalados globalmente com npm, pnpm, yarn, bun e deno, que marca cada um como usado recentemente, depend\xeancia de outro ou parado \u2014 e mostra comandos de desinstala\xe7\xe3o para voc\xea mesmo rodar.","permalink":"/pt-BR/modes/globals-audit"},{"id":"modes/speed","title":"Diagn\xf3stico de velocidade","description":"Confira temperatura, press\xe3o e o que inicia junto com o Linux, e decida se aplica cada mudan\xe7a sugerida.","permalink":"/pt-BR/modes/speed"},{"id":"modes/doctor","title":"Doctor","description":"Detecte runtimes instalados no disco mas ausentes da inicializa\xe7\xe3o do shell \u2014 nvm, pnpm, bun, deno, cargo \u2014 e acrescente o bloco de inicializa\xe7\xe3o padr\xe3o com a sua confirma\xe7\xe3o. S\xf3 acrescenta.","permalink":"/pt-BR/modes/doctor"},{"id":"modes/partial-downloads","title":"Downloads incompletos ou \xf3rf\xe3os","description":"Encontre e remova arquivos de downloads incompletos abandonados \u2014 .crdownload, .part e .fdmdownload \u2014 deixados por transfer\xeancias interrompidas de navegadores e gerenciadores de download.","permalink":"/pt-BR/modes/partial-downloads"},{"id":"modes/editor-extensions","title":"Extens\xf5es de editores","description":"Remova vers\xf5es substitu\xeddas de extens\xf5es do VS Code e do Cursor \u2014 as c\xf3pias antigas que ficam quando uma extens\xe3o atualiza \u2014 passando por uma checagem de substitui\xe7\xe3o e pelo limite de ociosidade.","permalink":"/pt-BR/modes/editor-extensions"},{"id":"modes/system-cleanup","title":"Limpeza do sistema (sudo)","description":"O modo de sistema com sudo: apt, journal, Snap, lista de kernels, arquivos antigos do /tmp e libera\xe7\xe3o opcional do cache de p\xe1ginas.","permalink":"/pt-BR/modes/system-cleanup"},{"id":"modes/node-modules-finder","title":"Localizador de node_modules parados","description":"Encontre pastas node_modules em projetos sem mexer h\xe1 N dias ou mais e apague de forma interativa. Muitas vezes \xe9 o que mais libera espa\xe7o na m\xe1quina de quem programa.","permalink":"/pt-BR/modes/node-modules-finder"},{"id":"modes/menu","title":"Menu","description":"O menu numerado que permite rodar uma categoria do linux-cleanup por vez em vez do passeio completo.","permalink":"/pt-BR/modes/menu"},{"id":"modes/walkthrough","title":"Passeio guiado (padr\xe3o)","description":"O modo padr\xe3o do linux-cleanup \u2014 dez etapas guiadas por todas as categorias de limpeza, com pergunta antes de cada uma, total acumulado e relat\xf3rio JSON da sess\xe3o.","permalink":"/pt-BR/modes/walkthrough"},{"id":"modes/reports","title":"Relat\xf3rios","description":"O passeio guiado pode gravar um registro JSON da sess\xe3o. Liste, veja, converta para Markdown ou HTML e exporte esses registros.","permalink":"/pt-BR/modes/reports"},{"id":"reference/modes-matrix","title":"Tabela de modos","description":"Todos os modos do linux-cleanup lado a lado: se apagam, se s\xe3o interativos, se usam sudo e se gravam um registro de sess\xe3o.","permalink":"/pt-BR/reference/modes-matrix"},{"id":"modes/all-safe","title":"Totalmente seguro (em lote)","description":"Limpe todos os caches regener\xe1veis de uma vez. O modo feito para cron e manuten\xe7\xe3o sem supervis\xe3o, e o \xfanico em que o --yes vale.","permalink":"/pt-BR/modes/all-safe"},{"id":"modes/tui","title":"TUI (menu visual)","description":"O menu visual com whiptail ou dialog, lan\xe7ado no linux-cleanup 1.3.0, que volta ao menu da CLI quando nenhum dos dois est\xe1 instalado.","permalink":"/pt-BR/modes/tui"},{"id":"modes/scan","title":"Verifica\xe7\xe3o (somente leitura)","description":"Confira ra\xedzes de cache, downloads incompletos e outros candidatos \xe0 limpeza no Linux sem apagar arquivos.","permalink":"/pt-BR/modes/scan"},{"id":"modes/overview","title":"Vis\xe3o geral dos modos","description":"Todos os modos do linux-cleanup agrupados pelo que fazem \u2014 inspe\xe7\xe3o somente leitura, limpeza guiada e em lote, modos interativos para dados pessoais e auxiliares de sa\xedda e reparo.","permalink":"/pt-BR/modes/overview"}],"unlisted":false}}')}}]);